    auto N   = x.size(0);
    auto Cin = x.size(1);
    auto D   = x.size(2);
    auto H   = x.size(3);
    auto W   = x.size(4);

    TORCH_CHECK(w.size(0) == Cin, \"w.size(0) must equal Cin\");
    auto Cout = w.size(1);
    auto K    = w.size(2);
    TORCH_CHECK(w.size(3) == K && w.size(4) == K, \"kernel must be square 3D\");

